<body>
<div id="container"></div>
<div id="hud">
  <div class="row">SCORE: <span id="score">0</span></div>
  <div class="row">LIVES: <span id="lives">3</span></div>
  <div class="row">HIGH: <span id="high">0</span></div>
  <div class="row" id="mode"></div>
</div>
<div id="banner">
  <h1 id="title">ATTRACT MODE</h1>
  <p id="subtitle">Press any key to play</p>
</div>
<script type="importmap">
{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js"}}
