<script type="module">
import * as THREE from 'three';

// --- Audio ---
let audioCtx = null;
function ensureAudio(){ if(!audioCtx){ audioCtx = new (window.AudioContext||window.webkitAudioContext)(); } if(audioCtx.state==='suspended') audioCtx.resume(); }
function tone(freq,dur,type='square',vol=0.08,slide=null){
  if(!audioCtx) return;
  const o=audioCtx.createOscillator(); const g=audioCtx.createGain();
  o.type=type; o.frequency.value=freq;
  if(slide) o.frequency.exponentialRampToValueAtTime(Math.max(1,slide), audioCtx.currentTime+dur);
  g.gain.value=vol; g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime+dur);
  o.connect(g); g.connect(audioCtx.destination);
  o.start(); o.stop(audioCtx.currentTime+dur);
}
function noise(dur,vol=0.2){
  if(!audioCtx) return;
  const sr=audioCtx.sampleRate; const buf=audioCtx.createBuffer(1,sr*dur,sr);
  const d=buf.getChannelData(0); for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1);
  const src=audioCtx.createBufferSource(); src.buffer=buf;
  const g=audioCtx.createGain(); g.gain.value=vol; g.gain.exponentialRampToValueAtTime(0.0001,audioCtx.currentTime+dur);
  const f=audioCtx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=1200;
  src.connect(f); f.connect(g); g.connect(audioCtx.destination);
  src.start(); src.stop(audioCtx.currentTime+dur);
}
// thrust loop
let thrustOsc=null, thrustGain=null;
function startThrust(){
  if(thrustOsc||!audioCtx) return;
  thrustOsc=audioCtx.createOscillator(); thrustGain=audioCtx.createGain();
  thrustOsc.type='sawtooth'; thrustOsc.frequency.value=60;
  thrustGain.gain.value=0.02;
  thrustOsc.connect(thrustGain); thrustGain.connect(audioCtx.destination);
  thrustOsc.start();
}
function stopThrust(){ if(thrustOsc){ thrustOsc.stop(); thrustOsc=null; thrustGain=null; } }

// --- Scene ---
const container=document.getElementById('container');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x000008);
scene.fog=new THREE.Fog(0x000008,80,300);
const camera=new THREE.PerspectiveCamera(60, innerWidth/innerHeight, 0.1, 1000);
const renderer=new THREE.WebGLRenderer({antialias:true});
renderer.setSize(innerWidth,innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
container.appendChild(renderer.domElement);

// lights
scene.add(new THREE.AmbientLight(0x404060,0.6));
const dir=new THREE.DirectionalLight(0xffffff,0.8); dir.position.set(50,80,50); scene.add(dir);

// stars
const starGeo=new THREE.BufferGeometry();
const starCount=2000;
const starPos=new Float32Array(starCount*3);
for(let i=0;i<starCount;i++){ starPos[i*3]=(Math.random()-0.5)*600; starPos[i*3+1]=(Math.random()-0.5)*600; starPos[i*3+2]=(Math.random()-0.5)*600; }
starGeo.setAttribute('position',new THREE.BufferAttribute(starPos,3));
const stars=new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xffffff,size:0.6,sizeAttenuation:true}));
scene.add(stars);

// --- State ---
const BOUNDS=140;
let state='attract'; // attract | playing | gameover
let score=0, lives=3, high=+localStorage.getItem('hs')||0;
let autopilot=false;
let lastInput=performance.now();
let gameoverTime=0;
const keys={};
let fireCooldown=0;
let invuln=0;
let thrusting=false;

// ship
const ship=new THREE.Group();
const bodyMat=new THREE.MeshStandardMaterial({color:0x00ffff, emissive:0x003344});
const body=new THREE.Mesh(new THREE.ConeGeometry(1.4,4.2,8), bodyMat);
body.rotation.x=-Math.PI/2;
ship.add(body);
const wingMat=new THREE.MeshStandardMaterial({color:0x0088aa});
const wing=new THREE.Mesh(new THREE.BoxGeometry(4.5,0.3,1.2), wingMat);
wing.position.z=0.5; ship.add(wing);
const engine=new THREE.Mesh(new THREE.SphereGeometry(0.6,8,8), new THREE.MeshBasicMaterial({color:0xff8800}));
engine.position.z=2.2; ship.add(engine);
scene.add(ship);
const shipVel=new THREE.Vector3();
let shipYaw=0;

// asteroids
const asteroids=[]; // {mesh,size,radius,vel,rot}
function astRadius(size){ return [6,3.5,2][size]; }
function astColor(size){ return [0x888888,0xaaaaaa,0xcccccc][size]; }
function createAsteroid(pos,size,vel){
  const r=astRadius(size);
  const geo=new THREE.IcosahedronGeometry(r,0);
  const mat=new THREE.MeshStandardMaterial({color:astColor(size),flatShading:true});
  const mesh=new THREE.Mesh(geo,mat);
  mesh.position.copy(pos);
  if(!vel){ const ang=Math.random()*Math.PI*2; const sp= (size===0?8:size===1?12:16); vel=new THREE.Vector3(Math.cos(ang)*sp,0,Math.sin(ang)*sp); }
  const a={mesh,size,radius:r,vel:vel.clone(),rot:new THREE.Vector3((Math.random()-0.5)*2,(Math.random()-0.5)*2,(Math.random()-0.5)*2)};
  asteroids.push(a);
  scene.add(mesh);
  return a;
}
function removeAsteroid(a){
  scene.remove(a.mesh); a.mesh.geometry.dispose(); a.mesh.material.dispose();
  const i=asteroids.indexOf(a); if(i>=0) asteroids.splice(i,1);
}

// bullets
const bullets=[];
function fireBullet(){
  const fwd=new THREE.Vector3(0,0,1).applyQuaternion(ship.quaternion);
  const pos=ship.position.clone().add(fwd.clone().multiplyScalar(2.5));
  const mesh=new THREE.Mesh(new THREE.SphereGeometry(0.35,8,8), new THREE.MeshBasicMaterial({color:0xffff00}));
  mesh.position.copy(pos); scene.add(mesh);
  bullets.push({mesh, vel:fwd.clone().multiplyScalar(60), life:2});
  tone(900,0.07,'square',0.06,400);
}

// particles
const particles=[];
function explode(pos,color=0xff6600,count=40){
  noise(0.35,0.18);
  tone(120,0.3,'sawtooth',0.06,40);
  for(let i=0;i<count;i++){
    const mesh=new THREE.Mesh(new THREE.SphereGeometry(0.25,6,6), new THREE.MeshBasicMaterial({color}));
    mesh.position.copy(pos); scene.add(mesh);
    const dir=new THREE.Vector3(Math.random()-0.5, (Math.random()-0.5)*0.5, Math.random()-0.5).normalize();
    const sp=5+Math.random()*15;
    particles.push({mesh, vel:dir.multiplyScalar(sp), life:0.8+Math.random()*0.6, maxLife:1.4, decay:1});
  }
}

// helpers
function normalizeAngle(a){ while(a>Math.PI) a-=Math.PI*2; while(a<-Math.PI) a+=Math.PI*2; return a; }
function clamp(v,min,max){ return Math.max(min,Math.min(max,v)); }

function resetGame(){
  score=0; lives=3;
  // clear
  bullets.forEach(b=>{scene.remove(b.mesh);b.mesh.geometry.dispose();b.mesh.material.dispose();}); bullets.length=0;
  asteroids.forEach(a=>removeAsteroid(a)); 
  particles.forEach(p=>{scene.remove(p.mesh);p.mesh.geometry.dispose();p.mesh.material.dispose();}); particles.length=0;
  ship.position.set(0,0,0); shipVel.set(0,0,0); ship.rotation.set(0,0,0); shipYaw=0;
  invuln=2;
  // spawn asteroids
  for(let i=0;i<5;i++) spawnAsteroidFar();
  updateHUD();
}
function spawnAsteroidFar(){
  const ang=Math.random()*Math.PI*2; const r=100+Math.random()*40;
  const pos=new THREE.Vector3(Math.cos(ang)*r,0,Math.sin(ang)*r);
  const size=Math.random()<0.5?0:(Math.random()<0.7?1:2);
  // ensure not too close to ship
  if(pos.length()<40) pos.set(40,0,0);
  createAsteroid(pos,size);
}

function updateHUD(){
  document.getElementById('score').textContent=score;
  document.getElementById('lives').textContent=lives;
  document.getElementById('high').textContent=high;
  const m = autopilot ? (state==='attract'?'ATTRACT (AI)':'AUTOPILOT') : (state==='attract'?'ATTRACT':'MANUAL');
  document.getElementById('mode').textContent=m;
}

function setBanner(title,sub){
  document.getElementById('title').textContent=title;
  document.getElementById('subtitle').textContent=sub;
  document.getElementById('banner').style.display='block';
}
function hideBanner(){ document.getElementById('banner').style.display='none'; }

// input
window.addEventListener('keydown', e=>{
  ensureAudio();
  keys[e.code]=true;
  lastInput=performance.now();
  if(state!=='playing'){ startPlaying(); return; }
  if(autopilot){ autopilot=false; updateHUD(); }
  if(e.code==='Space') e.preventDefault();
});
window.addEventListener('keyup', e=>{ keys[e.code]=false; });
window.addEventListener('mousedown', ()=>{ ensureAudio(); if(state!=='playing') startPlaying(); lastInput=performance.now(); });

function startPlaying(){
  state='playing'; autopilot=false;
  resetGame();
  hideBanner();
  updateHUD();
}

// AI
let aiTarget=null;
function nearestAsteroid(){
  let best=null,bestD=Infinity;
  for(const a of asteroids){
    const d=a.mesh.position.distanceTo(ship.position);
    if(d<bestD){bestD=d;best=a;}
  }
  return best;
}
function updateAI(dt){
  if(!aiTarget || !asteroids.includes(aiTarget)) aiTarget=nearestAsteroid();
  let turn=0; let thrust=false; let doFire=false;
  if(aiTarget){
    const tp=aiTarget.mesh.position;
    const dx=tp.x-ship.position.x; const dz=tp.z-ship.position.z;
    const dist=Math.hypot(dx,dz);
    const desired=Math.atan2(dx,dz);
    const diff=normalizeAngle(desired-ship.rotation.y);
    // avoidance
    let avoid=0;
    for(const a of asteroids){
      const d=a.mesh.position.distanceTo(ship.position);
      if(d<18){
        const ax=a.mesh.position.x-ship.position.x; const az=a.mesh.position.z-ship.position.z;
        // steer perpendicular away
        avoid += (ship.rotation.y - Math.atan2(ax,az)) >0 ? 1 : -1;
      }
    }
    if(Math.abs(avoid)>0) turn = avoid>0 ? 1 : -1;
    else turn = clamp(diff*2, -1, 1);
    if(Math.abs(diff)<0.35 && dist>10) thrust=true;
    // avoid close: back up
    if(dist<12){ thrust=false; }
    if(Math.abs(diff)<0.12 && dist<130 && fireCooldown<=0) doFire=true;
  } else {
    // no target: slow patrol
    turn=0.2; thrust=true;
  }
  return {turn,thrust,doFire};
}

// main loop
let last=performance.now();
function step(now){
  const dt=Math.min(0.05,(now-last)/1000); last=now;
  // idle check
  if(state==='playing' && !autopilot && (now-lastInput)>3000){ autopilot=true; updateHUD(); }
  // banner for gameover
  if(state==='gameover'){
    if(!document.getElementById('banner').style.display || document.getElementById('banner').style.display!=='none'){
      // keep
    }
    if(now-gameoverTime>6000){ state='attract'; autopilot=true; resetGame(); setBanner('ATTRACT MODE','Press any key to play'); updateHUD(); }
  }

  // inputs
  let thrust=false, turn=0;
  if(state==='playing'){
    if(autopilot){
      const ai=updateAI(dt);
      turn=ai.turn; thrust=ai.thrust;
      if(ai.doFire) fireBullet();
    } else {
      if(keys['ArrowUp']||keys['KeyW']) thrust=true;
      if(keys['ArrowLeft']||keys['KeyA']) turn+=1;
      if(keys['ArrowRight']||keys['KeyD']) turn-=1;
      if(keys['Space'] && fireCooldown<=0){ fireBullet(); fireCooldown=0.25; }
    }
  } else if(state==='attract'){
    autopilot=true;
    const ai=updateAI(dt);
    turn=ai.turn; thrust=ai.thrust;
    if(ai.doFire) fireBullet();
  }

  // movement
  if(state==='playing'||state==='attract'){
    ship.rotation.y += turn*3.2*dt;
    const fwd=new THREE.Vector3(0,0,1).applyQuaternion(ship.quaternion);
    if(thrust){
      shipVel.add(fwd.multiplyScalar(18*dt));
      if(!thrusting){ thrusting=true; startThrust(); }
    } else {
      if(thrusting){ thrusting=false; stopThrust(); }
    }
    shipVel.multiplyScalar(0.985);
    ship.position.add(shipVel.clone().multiplyScalar(dt));
    // clamp
    ship.position.x=clamp(ship.position.x,-BOUNDS,BOUNDS);
    ship.position.z=clamp(ship.position.z,-BOUNDS,BOUNDS);
    if(Math.abs(ship.position.x)===BOUNDS) shipVel.x=0;
    if(Math.abs(ship.position.z)===BOUNDS) shipVel.z=0;
    fireCooldown=Math.max(0,fireCooldown-dt);
    invuln=Math.max(0,invuln-dt);

    // bullets
    for(let i=bullets.length-1;i>=0;i--){
      const b=bullets[i];
      b.life-=dt; b.mesh.position.add(b.vel.clone().multiplyScalar(dt));
      if(b.life<=0 || Math.abs(b.mesh.position.x)>BOUNDS+10 || Math.abs(b.mesh.position.z)>BOUNDS+10){
        scene.remove(b.mesh); b.mesh.geometry.dispose(); b.mesh.material.dispose(); bullets.splice(i,1);
      }
    }

    // asteroids update
    for(const a of asteroids){
      a.mesh.position.add(a.vel.clone().multiplyScalar(dt));
      a.mesh.rotation.x+=a.rot.x*dt;
      a.mesh.rotation.y+=a.rot.y*dt;
      a.mesh.rotation.z+=a.rot.z*dt;
      // bounce
